class Solution:
    def twoSum(self, nums: list[int], target: int) -> list[int]:
        seen = {}
        for i, n in enumerate(nums):
            if target - n in seen:
                return [seen[target - n], i]
            seen[n] = i
        return []

class Solution:
    def removeDuplicates(self, nums: list[int]) -> int:
        k = 0
        for n in nums:
            if k == 0 or nums[k - 1] != n:
                nums[k] = n
                k += 1
        return k

class Solution:
    def maxProfit(self, prices: list[int]) -> int:
        best, low = 0, float("inf")
        for p in prices:
            low = min(low, p)
            best = max(best, p - low)
        return best

class Solution:
    def majorityElement(self, nums: list[int]) -> int:
        count, candidate = 0, None
        for n in nums:
            if count == 0:
                candidate = n
            count += 1 if n == candidate else -1
        return candidate

class Solution:
    def moveZeroes(self, nums: list[int]) -> None:
        k = 0
        for i, n in enumerate(nums):
            if n != 0:
                nums[k], nums[i] = nums[i], nums[k]
                k += 1

class Solution:
    def containsDuplicate(self, nums: list[int]) -> bool:
        return len(set(nums)) < len(nums)

class Solution:
    def missingNumber(self, nums: list[int]) -> int:
        n = len(nums)
        return n * (n + 1) // 2 - sum(nums)

class Solution:
    def singleNumber(self, nums: list[int]) -> int:
        out = 0
        for n in nums:
            out ^= n
        return out

class Solution:
    def plusOne(self, digits: list[int]) -> list[int]:
        out = digits[:]
        for i in range(len(out) - 1, -1, -1):
            if out[i] < 9:
                out[i] += 1
                return out
            out[i] = 0
        return [1] + out

class Solution:
    def merge(self, nums1: list[int], m: int, nums2: list[int], n: int) -> None:
        i, j, k = m - 1, n - 1, m + n - 1
        while j >= 0:
            if i >= 0 and nums1[i] > nums2[j]:
                nums1[k] = nums1[i]
                i -= 1
            else:
                nums1[k] = nums2[j]
                j -= 1
            k -= 1

class Solution:
    def sortedSquares(self, nums: list[int]) -> list[int]:
        out = [0] * len(nums)
        i, j = 0, len(nums) - 1
        for k in range(len(nums) - 1, -1, -1):
            if abs(nums[i]) > abs(nums[j]):
                out[k] = nums[i] ** 2
                i += 1
            else:
                out[k] = nums[j] ** 2
                j -= 1
        return out

class Solution:
    def rotate(self, nums: list[int], k: int) -> None:
        n = len(nums)
        k %= n
        nums[:] = nums[-k:] + nums[:-k] if k else nums[:]

class Solution:
    def productExceptSelf(self, nums: list[int]) -> list[int]:
        n = len(nums)
        out = [1] * n
        left = 1
        for i in range(n):
            out[i] = left
            left *= nums[i]
        right = 1
        for i in range(n - 1, -1, -1):
            out[i] *= right
            right *= nums[i]
        return out

class Solution:
    def maxSubArray(self, nums: list[int]) -> int:
        best = run = nums[0]
        for n in nums[1:]:
            run = max(n, run + n)
            best = max(best, run)
        return best

class Solution:
    def sortColors(self, nums: list[int]) -> None:
        low, i, high = 0, 0, len(nums) - 1
        while i <= high:
            if nums[i] == 0:
                nums[low], nums[i] = nums[i], nums[low]
                low += 1
                i += 1
            elif nums[i] == 2:
                nums[high], nums[i] = nums[i], nums[high]
                high -= 1
            else:
                i += 1

class Solution:
    def findDuplicate(self, nums: list[int]) -> int:
        slow = fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

class Solution:
    def threeSum(self, nums: list[int]) -> list[list[int]]:
        nums = sorted(nums)
        out = []
        for i in range(len(nums) - 2):
            if i and nums[i] == nums[i - 1]:
                continue
            lo, hi = i + 1, len(nums) - 1
            while lo < hi:
                total = nums[i] + nums[lo] + nums[hi]
                if total < 0:
                    lo += 1
                elif total > 0:
                    hi -= 1
                else:
                    out.append([nums[i], nums[lo], nums[hi]])
                    lo += 1
                    while lo < hi and nums[lo] == nums[lo - 1]:
                        lo += 1
        return out

class Solution:
    def maxArea(self, height: list[int]) -> int:
        lo, hi, best = 0, len(height) - 1, 0
        while lo < hi:
            best = max(best, (hi - lo) * min(height[lo], height[hi]))
            if height[lo] < height[hi]:
                lo += 1
            else:
                hi -= 1
        return best

class Solution:
    def merge(self, intervals: list[list[int]]) -> list[list[int]]:
        out = []
        for start, end in sorted(intervals):
            if out and start <= out[-1][1]:
                out[-1][1] = max(out[-1][1], end)
            else:
                out.append([start, end])
        return out

class Solution:
    def intersect(self, nums1: list[int], nums2: list[int]) -> list[int]:
        from collections import Counter
        counts = Counter(nums1)
        out = []
        for n in nums2:
            if counts[n] > 0:
                out.append(n)
                counts[n] -= 1
        return out

class Solution:
    def setZeroes(self, matrix: list[list[int]]) -> None:
        rows = {i for i, row in enumerate(matrix) for v in row if v == 0}
        cols = {j for row in matrix for j, v in enumerate(row) if v == 0}
        for i, row in enumerate(matrix):
            for j in range(len(row)):
                if i in rows or j in cols:
                    row[j] = 0

class Solution:
    def spiralOrder(self, matrix: list[list[int]]) -> list[int]:
        out = []
        top, bottom = 0, len(matrix) - 1
        left, right = 0, len(matrix[0]) - 1
        while top <= bottom and left <= right:
            for j in range(left, right + 1):
                out.append(matrix[top][j])
            top += 1
            for i in range(top, bottom + 1):
                out.append(matrix[i][right])
            right -= 1
            if top <= bottom:
                for j in range(right, left - 1, -1):
                    out.append(matrix[bottom][j])
                bottom -= 1
            if left <= right:
                for i in range(bottom, top - 1, -1):
                    out.append(matrix[i][left])
                left += 1
        return out

class Solution:
    def nextPermutation(self, nums: list[int]) -> None:
        i = len(nums) - 2
        while i >= 0 and nums[i] >= nums[i + 1]:
            i -= 1
        if i >= 0:
            j = len(nums) - 1
            while nums[j] <= nums[i]:
                j -= 1
            nums[i], nums[j] = nums[j], nums[i]
        nums[i + 1 :] = reversed(nums[i + 1 :])

class Solution:
    def trap(self, height: list[int]) -> int:
        if not height:
            return 0
        lo, hi = 0, len(height) - 1
        left, right, total = height[lo], height[hi], 0
        while lo < hi:
            if left <= right:
                lo += 1
                left = max(left, height[lo])
                total += left - height[lo]
            else:
                hi -= 1
                right = max(right, height[hi])
                total += right - height[hi]
        return total

class Solution:
    def firstMissingPositive(self, nums: list[int]) -> int:
        seen = set(nums)
        i = 1
        while i in seen:
            i += 1
        return i

class Solution:
    def findMedianSortedArrays(self, nums1: list[int], nums2: list[int]) -> float:
        merged = sorted(nums1 + nums2)
        n = len(merged)
        mid = n // 2
        if n % 2:
            return float(merged[mid])
        return (merged[mid - 1] + merged[mid]) / 2

class Solution:
    def largestRectangleArea(self, heights: list[int]) -> int:
        stack, best = [], 0
        for i, h in enumerate(heights + [0]):
            start = i
            while stack and stack[-1][1] > h:
                index, height = stack.pop()
                best = max(best, height * (i - index))
                start = index
            stack.append((start, h))
        return best

class Solution:
    def reverseString(self, s: list[str]) -> None:
        i, j = 0, len(s) - 1
        while i < j:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1

class Solution:
    def isPalindrome(self, s: str) -> bool:
        cleaned = [c.lower() for c in s if c.isalnum()]
        return cleaned == cleaned[::-1]

class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        from collections import Counter
        return Counter(s) == Counter(t)

class Solution:
    def longestCommonPrefix(self, strs: list[str]) -> str:
        if not strs:
            return ""
        prefix = strs[0]
        for word in strs[1:]:
            while not word.startswith(prefix):
                prefix = prefix[:-1]
                if not prefix:
                    return ""
        return prefix

class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        return haystack.find(needle)

class Solution:
    def firstUniqChar(self, s: str) -> int:
        from collections import Counter
        counts = Counter(s)
        for i, c in enumerate(s):
            if counts[c] == 1:
                return i
        return -1

class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        forward, backward = {}, {}
        for a, b in zip(s, t):
            if forward.setdefault(a, b) != b or backward.setdefault(b, a) != a:
                return False
        return len(s) == len(t)

class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        from collections import Counter
        return not (Counter(ransomNote) - Counter(magazine))

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        last = {}
        best = start = 0
        for i, c in enumerate(s):
            if c in last and last[c] >= start:
                start = last[c] + 1
            last[c] = i
            best = max(best, i - start + 1)
        return best

class Solution:
    def longestPalindrome(self, s: str) -> str:
        best = ""
        for i in range(len(s)):
            for lo, hi in ((i, i), (i, i + 1)):
                while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
                    lo -= 1
                    hi += 1
                if hi - lo - 1 > len(best):
                    best = s[lo + 1 : hi]
        return best

class Solution:
    def groupAnagrams(self, strs: list[str]) -> list[list[str]]:
        from collections import defaultdict
        groups = defaultdict(list)
        for word in strs:
            groups["".join(sorted(word))].append(word)
        return list(groups.values())

class Solution:
    def myAtoi(self, s: str) -> int:
        i, n = 0, len(s)
        while i < n and s[i] == " ":
            i += 1
        sign = 1
        if i < n and s[i] in "+-":
            sign = -1 if s[i] == "-" else 1
            i += 1
        digits = 0
        while i < n and s[i].isdigit():
            digits = digits * 10 + int(s[i])
            i += 1
        value = sign * digits
        return max(-2**31, min(2**31 - 1, value))

class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        from collections import Counter
        counts = Counter()
        start = best = most = 0
        for i, c in enumerate(s):
            counts[c] += 1
            most = max(most, counts[c])
            while i - start + 1 - most > k:
                counts[s[start]] -= 1
                start += 1
            best = max(best, i - start + 1)
        return best

class Solution:
    def frequencySort(self, s: str) -> str:
        from collections import Counter
        return "".join(c * n for c, n in Counter(s).most_common())

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        from collections import Counter
        if not t or not s:
            return ""
        need = Counter(t)
        missing = len(t)
        best = ""
        start = 0
        for i, c in enumerate(s):
            if need[c] > 0:
                missing -= 1
            need[c] -= 1
            while missing == 0:
                if not best or i - start + 1 < len(best):
                    best = s[start : i + 1]
                need[s[start]] += 1
                if need[s[start]] > 0:
                    missing += 1
                start += 1
        return best

class Solution:
    def containsNearbyDuplicate(self, nums: list[int], k: int) -> bool:
        last = {}
        for i, n in enumerate(nums):
            if n in last and i - last[n] <= k:
                return True
            last[n] = i
        return False

class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        words = s.split()
        if len(pattern) != len(words):
            return False
        forward, backward = {}, {}
        for c, word in zip(pattern, words):
            if forward.setdefault(c, word) != word:
                return False
            if backward.setdefault(word, c) != c:
                return False
        return True

class Solution:
    def intersection(self, nums1: list[int], nums2: list[int]) -> list[int]:
        return list(set(nums1) & set(nums2))

class Solution:
    def commonChars(self, words: list[str]) -> list[str]:
        from collections import Counter
        from functools import reduce
        shared = reduce(lambda a, b: a & b, (Counter(w) for w in words))
        return list(shared.elements())

class Solution:
    def uniqueOccurrences(self, arr: list[int]) -> bool:
        from collections import Counter
        counts = list(Counter(arr).values())
        return len(counts) == len(set(counts))

class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        from collections import Counter
        return [n for n, _ in Counter(nums).most_common(k)]

class Solution:
    def longestConsecutive(self, nums: list[int]) -> int:
        seen = set(nums)
        best = 0
        for n in seen:
            if n - 1 not in seen:
                length = 1
                while n + length in seen:
                    length += 1
                best = max(best, length)
        return best

class Solution:
    def fourSumCount(self, nums1, nums2, nums3, nums4) -> int:
        from collections import Counter
        pairs = Counter(a + b for a in nums1 for b in nums2)
        return sum(pairs[-(c + d)] for c in nums3 for d in nums4)

class Solution:
    def findAnagrams(self, s: str, p: str) -> list[int]:
        from collections import Counter
        if len(p) > len(s):
            return []
        need = Counter(p)
        window = Counter(s[: len(p)])
        out = [0] if window == need else []
        for i in range(len(p), len(s)):
            window[s[i]] += 1
            left = s[i - len(p)]
            window[left] -= 1
            if window[left] == 0:
                del window[left]
            if window == need:
                out.append(i - len(p) + 1)
        return out
